===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,162 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0">
+<title>Turbo Ball — Rocket League-inspired mini game</title>
+<style>
+  body{margin:0;background:#111;color:#fff;font-family:Arial,sans-serif;display:flex;flex-direction:column;align-items:center}
+  #hud{display:flex;gap:16px;align-items:center;margin:10px;font-size:18px;font-weight:bold}
+  #scoreBlue{color:#2a7fff}#scoreOrange{color:#ff7a1a}
+  #banner{position:absolute;top:38%;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:64px;font-weight:900;color:#ffd23f;text-shadow:0 0 24px #ff7a1a,0 4px 0 #000;display:none;pointer-events:none}
+  #wrap{position:relative}
+  canvas{border:3px solid #fff;border-radius:8px;background:#3aa72e;touch-action:none}
+  #controls{margin:8px;font-size:14px;opacity:.9;text-align:center;line-height:1.6}
+  button{font-size:16px;padding:6px 14px;border-radius:6px;border:0;cursor:pointer;font-weight:bold}
+  #boostBar{width:200px;height:12px;background:#333;border-radius:6px;overflow:hidden}
+  #boostFill{height:100%;width:100%;background:linear-gradient(90deg,#ffd23f,#ff7a1a)}
+</style>
+</head>
+<body>
+<div id="hud">
+  <span id="scoreBlue">BLUE 0</span><span>—</span><span id="scoreOrange">ORANGE 0</span>
+  <span id="timer">3:00</span>
+  <div id="boostBar" title="Boost"><div id="boostFill"></div></div>
+  <button id="restartBtn">Full restart</button>
+</div>
+<div id="wrap"><canvas id="game" width="960" height="540"></canvas><div id="banner">GOAL!</div></div>
+<div id="controls">Drive: <b>WASD / Arrows</b> &nbsp; Boost: <b>Shift / Space</b> &nbsp; Kickoff reset: <b>R</b> &nbsp; Full restart: <b>button</b> &nbsp; Score in the <b style="color:#ff7a1a">ORANGE goal (right)</b>. You are <b style="color:#2a7fff">BLUE</b>.</div>
+<script>
+const W=960,H=540,GOAL_H=150,GOAL_Y=(H-GOAL_H)/2;
+const cvs=document.getElementById('game'),ctx=cvs.getContext('2d');
+const banner=document.getElementById('banner'),boostFill=document.getElementById('boostFill');
+const scoreBlueEl=document.getElementById('scoreBlue'),scoreOrangeEl=document.getElementById('scoreOrange'),timerEl=document.getElementById('timer');
+function makeCar(x,y,angle,color,isAI){return{x,y,angle,vx:0,vy:0,r:15,color,isAI:!!isAI,boost:100};}
+let player=makeCar(300,270,0,'#2a7fff',false);
+let enemy=makeCar(660,270,Math.PI,'#ff7a1a',true);
+let ball={x:W/2,y:H/2,vx:0,vy:0,r:13};
+let pads=[{x:120,y:90},{x:480,y:90},{x:840,y:90},{x:120,y:450},{x:480,y:450},{x:840,y:450},{x:240,y:270},{x:720,y:270}].map(p=>({...p,active:true,t:0}));
+let parts=[],scores={blue:0,orange:0},frozen=false,timeLeft=180,keys={},last=performance.now(),shake=0;
+addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' ' )e.preventDefault();if(e.key.toLowerCase()==='r')reset(false);});
+addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
+document.getElementById('restartBtn').onclick=()=>reset(true);
+function reset(full){player=makeCar(300,270,0,'#2a7fff',false);enemy=makeCar(660,270,Math.PI,'#ff7a1a',true);
+ if(full){scores={blue:0,orange:0};timeLeft=180;}ball={x:W/2,y:H/2,vx:(Math.random()-.5)*60,vy:(Math.random()-.5)*60,r:13};frozen=false;banner.style.display='none';updateScore();}
+function updateScore(){scoreBlueEl.textContent='BLUE '+scores.blue;scoreOrangeEl.textContent='ORANGE '+scores.orange;}
+function flame(c){parts.push({x:c.x-Math.cos(c.angle)*20,y:c.y-Math.sin(c.angle)*20,vx:-Math.cos(c.angle)*260+(Math.random()-.5)*100,vy:-Math.sin(c.angle)*260+(Math.random()-.5)*100,life:.35,max:.35,col:c.color==='#2a7fff'?'#66b3ff':'#ffb066'});}
+function updateCar(c,dt,input,boosting){
+  const ACC=520,BOOST_ACC=1150,TURN=3.4;
+  const fx=Math.cos(c.angle),fy=Math.sin(c.angle);
+  const spd=Math.hypot(c.vx,c.vy);
+  const steer=(input.left?-1:0)+(input.right?1:0);
+  if(steer&&spd>30){const dir=(c.vx*fx+c.vy*fy)<0?-1:1;c.angle+=steer*TURN*dt*Math.min(1,spd/140)*dir;}
+  const nx=Math.cos(c.angle),ny=Math.sin(c.angle);
+  if(input.up){c.vx+=nx*ACC*dt;c.vy+=ny*ACC*dt;}
+  if(input.down){const f=c.vx*nx+c.vy*ny;if(f>20){c.vx-=nx*800*dt;c.vy-=ny*800*dt;}else{c.vx-=nx*300*dt;c.vy-=ny*300*dt;}}
+  if(boosting&&c.boost>0){c.vx+=nx*BOOST_ACC*dt;c.vy+=ny*BOOST_ACC*dt;c.boost=Math.max(0,c.boost-32*dt);flame(c);}
+  const d=Math.exp(-1.5*dt);c.vx*=d;c.vy*=d;
+  const s=Math.hypot(c.vx,c.vy),mx=(boosting&&c.boost>0)?560:340;if(s>mx){c.vx*=mx/s;c.vy*=mx/s;}
+  c.x+=c.vx*dt;c.y+=c.vy*dt;
+  // walls except goal mouths
+  const inMouth=c.y>GOAL_Y+6&&c.y<GOAL_Y+GOAL_H-6;
+  if(c.x<c.r+12){if(!(inMouth&&(c.x<24))) {c.x=c.r+12;c.vx=Math.abs(c.vx)*0.4;}}
+  if(c.x>W-c.r-12){if(!(inMouth)) {c.x=W-c.r-12;c.vx=-Math.abs(c.vx)*0.4;}}
+  if(c.y<c.r+12){c.y=c.r+12;c.vy=Math.abs(c.vy)*0.4;}
+  if(c.y>H-c.r-12){c.y=H-c.r-12;c.vy=-Math.abs(c.vy)*0.4;}
+  // goal box clamp: allow entering mouth slightly
+  c.x=Math.max(-20,Math.min(W+20,c.x));
+  for(const p of pads){if(p.active&&Math.hypot(c.x-p.x,c.y-p.y)<26){c.boost=Math.min(100,c.boost+35);p.active=false;p.t=5;}}
+}
+function collide(car,b){
+  const dx=b.x-car.x,dy=b.y-car.y,dist=Math.hypot(dx,dy)||.001,min=car.r+b.r;
+  if(dist>=min)return;
+  const nx=dx/dist,ny=dy/dist;b.x=car.x+nx*min;b.y=car.y+ny*min;
+  const rvx=b.vx-car.vx,rvy=b.vy-car.vy,vn=rvx*nx+rvy*ny;
+  if(vn<0){const j=-(1+0.95)*vn;b.vx+=nx*j+car.vx*0.45;b.vy+=ny*j+car.vy*0.45;
+    for(let i=0;i<8;i++)parts.push({x:b.x,y:b.y,vx:(Math.random()-.5)*300,vy:(Math.random()-.5)*300,life:.3,max:.3,col:'#fff'});
+    shake=Math.min(8,Math.abs(vn)/120);}
+  const s=Math.hypot(b.vx,b.vy);if(s>950){b.vx*=950/s;b.vy*=950/s;}
+}
+function onGoal(team){
+  scores[team]++;updateScore();frozen=true;shake=12;
+  banner.textContent=team==='blue'?'GOAL! BLUE SCORES!':'GOAL! ORANGE SCORES!';
+  banner.style.color=team==='blue'?'#66b3ff':'#ffd23f';banner.style.display='block';
+  for(let i=0;i<60;i++)parts.push({x:team==='blue'?W-30:30,y:H/2+(Math.random()-.5)*120,vx:(Math.random()-.5)*500,vy:(Math.random()-.5)*500,life:.8,max:.8,col:team==='blue'?'#2a7fff':'#ff7a1a'});
+  setTimeout(()=>{banner.style.display='none';player=makeCar(300,270,0,'#2a7fff',false);enemy=makeCar(660,270,Math.PI,'#ff7a1a',true);player.boost=100;enemy.boost=100;ball={x:W/2,y:H/2,vx:0,vy:0,r:13};frozen=false;},2000);
+}
+function aiInput(){
+  // simple chaser: aim at ball, or defend goal when ball near own goal
+  const gx=ball.x> W/2 ? 60 : W-60; // not used strictly; chase ball then shoot
+  const tx=ball.x,ty=ball.y;
+  const dx=tx-enemy.x,dy=ty-enemy.y,desired=Math.atan2(dy,dx);
+  let d=desired-enemy.angle;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;
+  return{up:true,down:false,left:d<-0.15,right:d>0.15,boost:Math.abs(d)<0.2&&Math.hypot(dx,dy)>220&&enemy.boost>20};
+}
+function frame(now){
+  let dt=Math.min(0.033,(now-last)/1000);last=now;
+  if(!frozen){
+    timeLeft-=dt;if(timeLeft<=0){timeLeft=0;banner.textContent=scores.blue===scores.orange?'DRAW!':(scores.blue>scores.orange?'BLUE WINS!':'ORANGE WINS!');banner.style.display='block';frozen=true;setTimeout(()=>{reset(true);},3000);}
+    const m=Math.floor(timeLeft/60),s=Math.floor(timeLeft%60);timerEl.textContent=m+':'+String(s).padStart(2,'0');
+    const inp={up:keys['w']||keys['arrowup'],down:keys['s']||keys['arrowdown'],left:keys['a']||keys['arrowleft'],right:keys['d']||keys['arrowright']};
+    const boosting=keys['shift']||keys[' '];
+    updateCar(player,dt,inp,boosting);
+    const ai=aiInput();updateCar(enemy,dt,ai,ai.boost);
+    // ball physics
+    const f=Math.pow(0.992,dt*60);ball.vx*=f;ball.vy*=f;
+    ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;
+    if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy)*0.8;}
+    if(ball.y>H-ball.r){ball.y=H-ball.r;ball.vy=-Math.abs(ball.vy)*0.8;}
+    const inMouthY=ball.y>GOAL_Y&&ball.y<GOAL_Y+GOAL_H;
+    if(!inMouthY){
+      if(ball.x<ball.r+12){ball.x=ball.r+12;ball.vx=Math.abs(ball.vx)*0.8;}
+      if(ball.x>W-ball.r-12){ball.x=W-ball.r-12;ball.vx=-Math.abs(ball.vx)*0.8;}
+    }
+    collide(player,ball);collide(enemy,ball);
+    // goals: fully past line inside mouth
+    if(ball.x<-10&&inMouthY)onGoal('orange');
+    if(ball.x>W+10&&inMouthY)onGoal('blue');
+    for(const p of pads){if(!p.active){p.t-=dt;if(p.t<=0)p.active=true;}}
+  }
+  // particles
+  for(const p of parts){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;}
+  parts=parts.filter(p=>p.life>0);
+  boostFill.style.width=player.boost+'%';
+  draw();requestAnimationFrame(frame);
+}
+function drawCar(c){
+  ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);
+  ctx.fillStyle='rgba(0,0,0,.3)';ctx.fillRect(-16,-12+3,34,22);
+  ctx.fillStyle=c.color;ctx.beginPath();ctx.roundRect(-16,-11,34,22,6);ctx.fill();
+  ctx.fillStyle='rgba(255,255,255,.85)';ctx.fillRect(-2,-8,12,16); // cabin
+  ctx.fillStyle='#111';[[-12,-14],[4,-14],[-12,10],[4,10]].forEach(([x,y])=>{ctx.fillRect(x,y,10,5);});
+  ctx.fillStyle='#ffd23f';ctx.fillRect(14,-6,4,12); // headlights
+  ctx.restore();
+}
+function draw(){
+  ctx.save();
+  if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=0.88;if(shake<0.3)shake=0;}
+  // pitch + mow stripes
+  ctx.fillStyle='#3aa72e';ctx.fillRect(0,0,W,H);
+  ctx.fillStyle='rgba(255,255,255,.06)';for(let i=0;i<8;i++)if(i%2===0)ctx.fillRect(i*W/8,0,W/8,H);
+  ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.strokeRect(12,12,W-24,H-24);
+  ctx.beginPath();ctx.moveTo(W/2,12);ctx.lineTo(W/2,H-12);ctx.stroke();
+  ctx.beginPath();ctx.arc(W/2,H/2,65,0,Math.PI*2);ctx.stroke();
+  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(W/2,H/2,5,0,Math.PI*2);ctx.fill();
+  // goals: blue left, orange right
+  ctx.fillStyle='#2a7fff';ctx.fillRect(0,GOAL_Y,16,GOAL_H);
+  ctx.fillStyle='#ff7a1a';ctx.fillRect(W-16,GOAL_Y,16,GOAL_H);
+  ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(0,GOAL_Y,16,GOAL_H);ctx.strokeRect(W-16,GOAL_Y,16,GOAL_H);
+  // boost pads
+  for(const p of pads){ctx.globalAlpha=p.active?1:0.25;ctx.fillStyle='#ffd23f';ctx.beginPath();ctx.arc(p.x,p.y,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7a5200';ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
+  // ball with pentagon hint
+  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();
+  ctx.strokeStyle='#222';ctx.lineWidth=2;ctx.stroke();
+  ctx.fillStyle='#222';ctx.beginPath();ctx.arc(ball.x,ball.y,4,0,Math.PI*2);ctx.fill();
+  drawCar(player);drawCar(enemy);
+  for(const p of parts){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.col;ctx.beginPath();ctx.arc(p.x,p.y,3.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
+  ctx.restore();
+}
+updateScore();requestAnimationFrame(frame);
+</script>
+</body>
+</html>

